changeSet.sql:
-- Player letters and "players by letter" lookups.
CREATE INDEX IF NOT EXISTS player_letter_name_idx
    ON player (upper(left(name, 1)), lower(name))
    WHERE alias_of_player_id IS NULL AND lower(name) != 'skip';

-- Default player list ordering (no search term).
CREATE INDEX IF NOT EXISTS player_display_label_idx
    ON player (lower(coalesce(nullif(display_name, ''), name)))
    WHERE alias_of_player_id IS NULL;

ANALYZE player;
ANALYZE match_player;
